		CPacketMsg *msg = new CPacketMsg;
		if (msg == NULL)
			return NULL;
		msg->m_size = in->m_len;
		msg->m_data = (unsigned char *)calloc(msg->m_size + 1, 1);
		memcpy(msg->m_data, buf, msg->m_size);
		_counter = in->m_id;
		msg->m_args = NULL;
